import{_ as e,o as s,c as n,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"33. Typedef 和代码清晰度","description":"The Little Book of C 中文版 — 33. Typedef 和代码清晰度","frontmatter":{"title":"33. Typedef 和代码清晰度","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","04-数据结构","中文"],"description":"The Little Book of C 中文版 — 33. Typedef 和代码清晰度","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":33,"sidebarWeight":33,"alternateZh":"/posts/c教程/zh-CN/04-数据结构/033-Typedef and Code Clarity","alternateEn":"/posts/c教程/en-US/04-Structuring Data/033-Typedef and Code Clarity"},"headers":[],"relativePath":"posts/c教程/zh-CN/04-数据结构/033-Typedef and Code Clarity.md","filePath":"posts/c教程/zh-CN/04-数据结构/033-Typedef and Code Clarity.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/04-数据结构/033-Typedef and Code Clarity.md"};function i(d,a,l,o,c,r){return s(),n("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/04-Structuring Data/033-Typedef and Code Clarity)</p><p>C 使您能够使用以下命令创建自己的类型名称<code>typedef</code>关键词。它不会在运行时创建新类型，而是创建别名，使您的代码更清晰、更具表现力且更易于维护。</p><p>如果<code>struct</code>,<code>enum</code>，或者指针语法感觉很混乱，<code>typedef</code>是你最好的朋友。</p><h4 id="什么是-typedef" tabindex="-1">什么是 typedef？ <a class="header-anchor" href="#什么是-typedef" aria-label="Permalink to &quot;什么是 typedef？&quot;">​</a></h4><p><code>typedef</code>给现有类型一个新名称。它就像一个复杂或经常使用的声明的昵称。</p><p>句法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef existing_type new_name;</span></span></code></pre></div><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef unsigned long ulong;</span></span></code></pre></div><p>现在<code>ulong</code>可以在您通常编写的任何地方使用<code>unsigned long</code>.</p><h4 id="基本示例" tabindex="-1">基本示例 <a class="header-anchor" href="#基本示例" aria-label="Permalink to &quot;基本示例&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>typedef int Score;</span></span>
<span class="line"><span>typedef char Letter;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    Score math = 95;</span></span>
<span class="line"><span>    Letter grade = &#39;A&#39;;</span></span>
<span class="line"><span>    printf(&quot;Math: %d, Grade: %c\\n&quot;, math, grade);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Math: 95, Grade: A</span></span></code></pre></div><p>它不会改变编译器处理变量的方式，只是使代码更具可读性。</p><h4 id="带指针的-typedef" tabindex="-1">带指针的 Typedef <a class="header-anchor" href="#带指针的-typedef" aria-label="Permalink to &quot;带指针的 Typedef&quot;">​</a></h4><p>指针声明可能会变得混乱。和<code>typedef</code>，你可以简化它们。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef int* IntPtr;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    IntPtr p = &amp;x; // same as int *p = &amp;x;</span></span>
<span class="line"><span>    printf(&quot;Value: %d\\n&quot;, *p);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Value: 10</span></span></code></pre></div><p>提示：要小心，<code>IntPtr a, b;</code>意味着两者<code>a</code>和<code>b</code>是指针，与普通的不同<code>int *a, b;</code>.</p><h4 id="带有结构的-typedef" tabindex="-1">带有结构的 Typedef <a class="header-anchor" href="#带有结构的-typedef" aria-label="Permalink to &quot;带有结构的 Typedef&quot;">​</a></h4><p><code>typedef</code>闪耀着<code>struct</code>,<code>union</code>， 和<code>enum</code>声明。没有类型定义：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct Point {</span></span>
<span class="line"><span>    int x;</span></span>
<span class="line"><span>    int y;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>struct Point p1 = {3, 4};</span></span></code></pre></div><p>使用 typedef：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef struct {</span></span>
<span class="line"><span>    int x;</span></span>
<span class="line"><span>    int y;</span></span>
<span class="line"><span>} Point;</span></span>
<span class="line"><span>Point p1 = {3, 4};</span></span></code></pre></div><p>不再需要重复这个词<code>struct</code>到处。</p><h4 id="结合结构和-typedef" tabindex="-1">结合结构和 Typedef <a class="header-anchor" href="#结合结构和-typedef" aria-label="Permalink to &quot;结合结构和 Typedef&quot;">​</a></h4><p>您可以在一行中定义一个结构体并为其添加别名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef struct Person {</span></span>
<span class="line"><span>    char name[50];</span></span>
<span class="line"><span>    int age;</span></span>
<span class="line"><span>} Person;</span></span></code></pre></div><p>现在你可以写：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Person p = {&quot;Alice&quot;, 25};</span></span></code></pre></div><p>而不是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct Person p = {&quot;Alice&quot;, 25};</span></span></code></pre></div><h4 id="带有函数指针的-typedef" tabindex="-1">带有函数指针的 Typedef <a class="header-anchor" href="#带有函数指针的-typedef" aria-label="Permalink to &quot;带有函数指针的 Typedef&quot;">​</a></h4><p>函数指针语法可能难以阅读，typedef 极大地简化了它。</p><p>没有类型定义：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int (*operation)(int, int);</span></span></code></pre></div><p>使用 typedef：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef int (*Operation)(int, int);</span></span>
<span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    Operation op = add;</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, op(2, 3));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在<code>Operation</code>是一个指向函数的指针的干净别名，该函数接受两个 int 并返回一个 int。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>下面是一个完整的示例，显示了结构体、指针和函数类型的 typedef：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>typedef struct {</span></span>
<span class="line"><span>    char name[50];</span></span>
<span class="line"><span>    int age;</span></span>
<span class="line"><span>} Person;</span></span>
<span class="line"><span>typedef Person* PersonPtr;</span></span>
<span class="line"><span>typedef void (*Printer)(const Person*);</span></span>
<span class="line"><span>void print_person(const Person *p) {</span></span>
<span class="line"><span>    printf(&quot;%s (%d years old)\\n&quot;, p-&gt;name, p-&gt;age);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    Person p = {&quot;Alice&quot;, 25};</span></span>
<span class="line"><span>    PersonPtr ptr = &amp;p;</span></span>
<span class="line"><span>    Printer print = print_person;</span></span>
<span class="line"><span>    print(ptr);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alice (25 years old)</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p><code>typedef</code>改进：</p><ul><li>清晰度：长或复杂的声明变得可读。</li><li>一致性：标准化命名（例如，<code>size_t</code>,<code>uint32_t</code>).</li><li>可维护性：更改底层类型更容易，一次 typedef 更改会更新所有用途。</li><li>抽象：隐藏实现细节，尤其是在标头中。</li></ul><p>它在大型项目和系统 API 中特别有用，其中命名约定定义了清晰的边界。</p><h4 id="常见的-typedef-模式" tabindex="-1">常见的 Typedef 模式 <a class="header-anchor" href="#常见的-typedef-模式" aria-label="Permalink to &quot;常见的 Typedef 模式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>目的</th><th>示例</th></tr></thead><tbody><tr><td>标准别名</td><td><code>typedef unsigned int uint;</code></td></tr><tr><td>结构抽象</td><td><code>typedef struct Node Node;</code></td></tr><tr><td>函数指针类型</td><td><code>typedef void (*Handler)(int signal);</code></td></tr><tr><td>手柄状图案</td><td><code>typedef struct File* FileHandle;</code></td></tr><tr><td>平台类型</td><td><code>typedef long long int64; typedef unsigned int uint32;</code></td></tr></tbody></table><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>定义一个<code>typedef</code>为了<code>unsigned long long</code>被称为<code>u64</code>.</li><li>创建一个<code>typedef struct</code>被称为<code>Book</code>包含标题和页面字段。</li><li>定义一个<code>typedef</code>对于函数指针<code>Comparator(int, int)</code>.</li><li>编写一个程序，通过<code>Comparator</code>到排序功能。</li><li>修改一个 typedef 并观察代码如何在无需进一步编辑的情况下干净地编译。</li></ol><p><code>typedef</code>可能看起来很简单，但它是 C 语言中最强大的可读性工具之一。它可以让您为您的系统设计自己的词汇表，这是朝着编写可扩展的干净、自记录代码迈出的一小步。</p>`,55)])])}const g=e(t,[["render",i]]);export{u as __pageData,g as default};
